# %%
from pathlib import Path

import gmsh
import ogstools as ot
import pyvista as pv


# %%
class SingleJointLIEMesh:
    """Mesh generator for geo2d.geo (generated by geo2py).

    Converted via the gmsh unroll path, because the source uses constructs
    that are expanded before conversion (Coherence).  The geometry is
    exact, but the original .geo parameters are not exposed as arguments.

    Geometry: 6 points, 7 curves, 2 surfaces.
    Physical groups: FRACTURE, ROCK.
    """

    def __init__(self, gmsh_model, cl__1=1):
        # cl__1 = 1
        self.gmsh_model = gmsh_model

        if not gmsh.isInitialized():
            gmsh.initialize()

        self.out_dir = None

        geo = gmsh.model.geo

        # Entities, keyed by their tag in the original .geo file.
        p, c, cl, s, sl, v = {}, {}, {}, {}, {}, {}

        # --- Points (keys are the tags of the original .geo file) ---
        coords = {
            1: (0.1, 0),
            2: (12.6, 0),
            3: (12.6, 1),
            4: (12.6, 0.5),
            5: (0.1, 1),
            6: (0.1, 0.5),
        }
        for tag, (x, y) in coords.items():
            p[tag] = geo.addPoint(x, y, 0.0, cl__1, tag)

        # --- Curves (keys are the tags of the original .geo file) ---
        lines = {  # start, end
            1: (1, 2),
            2: (2, 4),
            3: (4, 3),
            4: (6, 4),
            5: (1, 6),
            6: (6, 5),
            7: (5, 3),
        }
        for tag, pts in lines.items():
            c[tag] = geo.addLine(*(p[t] for t in pts), tag)

        # --- Surfaces ---
        # A negative tag reverses the curve, as in the .geo file.
        loops = {
            1: [-5, 1, 2, -4],
            2: [-6, 4, 3, -7],
        }
        for tag, tags in loops.items():
            cl[tag] = geo.addCurveLoop([c[t] if t > 0 else -c[-t] for t in tags], tag)

        surfaces = {
            1: [1],
            2: [2],
        }
        for tag, tags in surfaces.items():
            s[tag] = geo.addPlaneSurface(
                [cl[t] if t > 0 else -cl[-t] for t in tags], tag
            )

        # --- Transfinite setup ---
        for tag in (1,):
            geo.mesh.setTransfiniteCurve(c[tag], 35, "Progression", 1)
        for tag in (2,):
            geo.mesh.setTransfiniteCurve(c[tag], 20, "Progression", 0.9)
        for tag in (3,):
            geo.mesh.setTransfiniteCurve(c[tag], 20, "Progression", 1.1)
        for tag in (4,):
            geo.mesh.setTransfiniteCurve(c[tag], 35, "Progression", 1)
        for tag in (5,):
            geo.mesh.setTransfiniteCurve(c[tag], 20, "Progression", 0.9)
        for tag in (6,):
            geo.mesh.setTransfiniteCurve(c[tag], 20, "Progression", 1.1)
        for tag in (7,):
            geo.mesh.setTransfiniteCurve(c[tag], 35, "Progression", 1)
        geo.mesh.setTransfiniteSurface(s[1], "Left", [p[1], p[2], p[4], p[6]])
        for tag in (1,):
            geo.mesh.setRecombine(2, s[tag])
        geo.mesh.setTransfiniteSurface(s[2], "Left", [p[6], p[4], p[3], p[5]])
        for tag in (2,):
            geo.mesh.setRecombine(2, s[tag])

        # --- Boundaries (names as in geo2d.geo) ---
        self.surfaces = [s[t] for t in (1, 2)]
        self.fracture_boundary = [c[t] for t in (4,)]
        # Physical Surface "ROCK" covered every entity; it is the "domain" group.

        # (dim, entity tags, physical tag, name), registered by
        # generate_meshes.  The bulk group is first and is always
        # named "domain", which is what OGS expects.
        self.physical_groups = [
            (2, self.surfaces, 1, "domain"),
            (1, self.fracture_boundary, None, "FRACTURE"),
        ]

        # --- Synchronize ---
        self.gmsh_model.geo.synchronize()

    def generate_meshes(self, out_dir="", order=1):
        self.out_dir = Path(out_dir)
        if not self.out_dir.exists():
            self.out_dir.mkdir(parents=True)

        gmsh.option.setNumber("Mesh.Algorithm", 5)
        gmsh.option.setNumber("Mesh.Format", 1)

        # Always mesh linear in Gmsh; order-2 meshes are produced below via
        # createQuadraticMesh, because ot.cli().NodeReordering does not work for
        # higher order elements generated from Gmsh.
        # Set explicitly, because ~/.gmsh-options may set Mesh.ElementOrder = 2.
        gmsh.option.setNumber("Mesh.ElementOrder", 1)

        # --- Mesh generation ---
        self.gmsh_model.mesh.generate(2)

        # Optional GUI
        # if "-nopopup" not in sys.argv:
        #    gmsh.fltk.run()

        self.gmsh_model.removePhysicalGroups()
        bulk_mesh_name = "domain"
        for dim, tags, physical_tag, name in self.physical_groups:
            named = {} if name is None else {"name": name}
            self.gmsh_model.addPhysicalGroup(
                dim, tags, -1 if physical_tag is None else physical_tag, **named
            )
        bulk_mesh_name = Path(self.out_dir, bulk_mesh_name + ".vtu")

        # Set output format to MSH2
        gmsh.option.setNumber("Mesh.MshFileVersion", 2.2)
        mesh_name = "domain.msh"
        mesh_file_name = Path(self.out_dir, mesh_name)
        gmsh.write(str(mesh_file_name))

        # `dim` is ommitted for converting all meshes
        meshes = ot.Meshes.from_gmsh(mesh_file_name)

        vtu_names = []
        for name, mesh in meshes.items():
            print(f"{name}: {mesh.n_cells} cells")
            if "physical_group_" in name:
                vtu_name = Path(
                    self.out_dir, f"{name.replace('physical_group_', '')}.vtu"
                )
            else:
                vtu_name = Path(self.out_dir, f"{name}.vtu")
            vtu_names.append(vtu_name)
            pv.save_meshio(vtu_name, mesh)

        ot.cli().NodeReordering("-i", bulk_mesh_name, "-o", bulk_mesh_name)
        if order == 2:
            files_to_process = {bulk_mesh_name, *vtu_names}
            for vtu_file_name in files_to_process:
                print(f"Create quadratic mesh for {vtu_file_name}")
                ot.cli().createQuadraticMesh("-i", vtu_file_name, "-o", vtu_file_name)

        ot.cli().identifySubdomains(
            "-m",
            bulk_mesh_name,
            f"-o {self.out_dir}/",
            "-f",
            "-s 1e-6",
            "--",
            *vtu_names,
        )


# %%
if __name__ == "__main__":
    gmsh.initialize(readConfigFiles=False)
    gmsh.model.add("single_joint_LIE")
    generator = SingleJointLIEMesh(gmsh.model)
    generator.generate_meshes(out_dir="02_LIE_EFPM_Fault-Controlled_Injection/input_meshes_single_joint_LIE")
    gmsh.finalize()
